'use strict';
const form=document.querySelector('#search-form'),nameInput=document.querySelector('#student-name'),department=document.querySelector('#department'),results=document.querySelector('#results'),clear=document.querySelector('#clear-search'),searchButton=document.querySelector('#search-button');
let students=[],loaded=false,searched=false;
const {normalize,findStudents}=AdmissionSearch;
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
function message(title,description,icon='⌕'){results.replaceChildren();const box=el('div','empty-state');box.append(el('div','empty-icon',icon));const copy=el('div');copy.append(el('h3','',title),el('p','',description));box.append(copy);results.append(box);}
function reset(){searched=false;document.querySelectorAll('.printing').forEach(x=>x.classList.remove('printing'));message('نتيجتك بانتظار البحث',loaded?'أدخل اسمك واضغط «ابحث عن نتيجتي» لعرض النتيجة.':'جاري تحميل قائمة الترشيحات…','⌕');}
function search(event){if(event)event.preventDefault();if(!loaded)return;searched=true;const q=nameInput.value.trim();if(normalize(q).length<3){message('اكتب 3 أحرف على الأقل','أضف اسم الأب أو الجد للحصول على نتيجة أدق.');nameInput.focus();return;}const matches=findStudents(students,q,department.value);results.replaceChildren();if(!matches.length){message('لم نعثر على اسم مطابق','تأكد من كتابة الاسم كما في المستمسكات أو ابحث بجزء منه، وجرّب اختيار جميع الأقسام. عدم ظهور الاسم هنا لا يعني صدور قرار برفض القبول.','!');return;}
 const heading=el('div','results-heading');heading.append(el('h3','',matches.length===1?'نتيجة البحث':'الأسماء المطابقة للبحث'),el('span','',matches.length+' '+(matches.length===1?'نتيجة':'نتيجة مطابقة')));results.append(heading);
 if(matches.length>20)results.append(el('p','more-notice','نعرض أول 20 نتيجة من '+matches.length+'. أضف اسم الأب أو الجد لتحديد نتيجتك.'));
 const list=el('div','result-list');for(const s of matches.slice(0,20)){const card=el('article','result-card');const top=el('div','result-top');const badge=el('span','accepted-badge','✓ مرشح للقبول');top.append(badge,el('span','result-year','2026 / 2027'));const title=el('h4','student-name',s.name);const detail=el('div','department-result');detail.append(el('span','detail-label','القسم المرشح للقبول'),el('strong','',s.department));const bottom=el('div','result-bottom');bottom.append(el('span','study-tag','الدراسة المسائية'));const print=el('button','print-button','طباعة النتيجة ↗');print.type='button';print.setAttribute('aria-label','طباعة نتيجة '+s.name);print.addEventListener('click',()=>{document.querySelectorAll('.printing').forEach(x=>x.classList.remove('printing'));card.classList.add('printing');window.print();});bottom.append(print);card.append(top,title,detail,bottom);list.append(card);}results.append(list);}
form.addEventListener('submit',search);nameInput.addEventListener('input',()=>{clear.hidden=!nameInput.value;if(searched)reset();});department.addEventListener('change',()=>{if(searched)search();});clear.addEventListener('click',()=>{nameInput.value='';clear.hidden=true;reset();nameInput.focus();});window.addEventListener('afterprint',()=>document.querySelectorAll('.printing').forEach(x=>x.classList.remove('printing')));
fetch('students.json').then(r=>{if(!r.ok)throw new Error('load');return r.json();}).then(data=>{if(!Array.isArray(data)||data.length===0||data.some(s=>!s.name||!s.department))throw new Error('data');students=data;const departments=[...new Set(data.map(s=>s.department))].sort((a,b)=>a.localeCompare(b,'ar'));for(const d of departments){const option=el('option','',d);option.value=d;department.append(option);}document.querySelector('#student-count').textContent=data.length;document.querySelector('#department-count').textContent=departments.length;loaded=true;searchButton.disabled=false;reset();}).catch(()=>{message('تعذّر تحميل قائمة الترشيحات','تحقق من اتصال الإنترنت وأعد تحميل الصفحة.','!');const retry=el('button','retry-button','إعادة المحاولة');retry.addEventListener('click',()=>location.reload());results.append(retry);});
